--{{{ ---返回查看家园信息
function PersonalHomeSubsystem:RecvMsg_LookHomeInfo(data)
    ---@type SC_GetUserHome
    local msg = assert(Dll_PB.decode("GetUserHome", data))
    log(" 返回查看家园信息  ",ProtoMsgHelp.block(msg))
    if msg then
        --if msg.reqrid ~= PlayerDataManager:Get():GetPlayerRID() then ---目前个人信息是二d场景  看其他人是3d
            SkipModuleHelper:Get():ToPlayerInfoView(SkipPlayerInfoView.PersonalHome)
        --end
        local info={
            msg.reqrid,
            msg.rolename,
            msg.guildname,
            msg.sign,
            msg.curlevel,
            msg.headicon,
            msg.iconframe
        }
        if msg.reqrid == PlayerDataManager:Get():GetPlayerRID() then
            if msg.myFurniture~=nil then
                PersonalHomeDataManager:Get():UpdatePersonalHomeData(msg.myFurniture)
            end
            UINotify:Get():SendNotification(UINotifyEvent.PersonalHomeViewSetData, { SkipPlayerInfoView.PlayerInfo,info })
        else
            UINotify:Get():SendNotification(UINotifyEvent.PersonalHomeViewSetData, { SkipPlayerInfoView.OtherPlayerInfo,info})
        end
        PersonalHomeDataManager:Get():InitHomeExhibit(msg.reqrid,msg.homeinfo,msg.cars)
    end
end
--}}}

