function PersonalHomeSubsystem:RecvMsg_AddExhibit()

    local cupboard = self:GetExhibitByServerID(5)
    local jiangbei2 = self:GetExhibitByServerID(102)
    self:UpdateExhibitNode(jiangbei2,cupboard:GetServerID(),102)

    PersonalHomeDataManager:Get():AddExhibit()
end
